try:
    stripped_format_type = format_type.strip().upper()
    numobj = phonenumbers.parse(e164_number, None)
    format_map = {
        "E164": PhoneNumberFormat.E164,
        "INTERNATIONAL": PhoneNumberFormat.INTERNATIONAL,
        "NATIONAL": PhoneNumberFormat.NATIONAL
    }
    if stripped_format_type not in format_map:
        raise ValueError(f"Invalid format type: {format_type}")

    target_format = format_map[stripped_format_type]
    formatted_string = phonenumbers.format_number(numobj, target_format)

    return {
        "format_number_string": formatted_string,
        "success": True,
        "error": None
    }
except Exception as e:
    return {
        "format_number_string": None,
        "success": False,
        "error": str(e)
    }

try:
    numobj = phonenumbers.parse(e164_number, None)
    carrier = phonenumbers.carrier(numobj)

    return {
        "carrier_name": carrier if carrier else "UNKNOWN",
        "success": True,
        "error": None
    }
except Exception as e:
    return {
        "carrier_name": None,
        "success": False,
        "error": str(e)
    }
